private extension EditorCanvasView.Item {
    init?(stateItem: EditorCanvasState.Item) {
        switch stateItem {
        case .pen(let points, let color, let lineWidth):
            self = .pen(points: points.map(\.nsPoint), color: color.nsColor, lineWidth: lineWidth)
        case .arrow(let start, let end, let color, let lineWidth):
            self = .arrow(start: start.nsPoint, end: end.nsPoint, color: color.nsColor, lineWidth: lineWidth)
        case .rect(let rect, let color, let lineWidth):
            self = .rect(rect: rect.nsRect, color: color.nsColor, lineWidth: lineWidth)
        case .ellipse(let rect, let color, let lineWidth):
            self = .ellipse(rect: rect.nsRect, color: color.nsColor, lineWidth: lineWidth)
        case .text(let text):
            let item = EditorCanvasView.TextItem(text: text.text,
                                                 origin: text.origin.nsPoint,
                                                 color: text.color.nsColor,
                                                 fontSize: text.fontSize)
            self = .text(item)
        case .image(let pngData, let rect):
            guard let image = NSImage(data: pngData) else { return nil }
            self = .image(image: image, rect: rect.nsRect)
        case .erase(let rect):
            self = .erase(rect: rect.nsRect)
        }
    }

    var stateItem: EditorCanvasState.Item? {
        switch self {
        case .pen(let points, let color, let lineWidth):
            return .pen(points: points.map(EditorCanvasState.Point.init),
                        color: EditorCanvasState.Color(color),
                        lineWidth: lineWidth)
        case .arrow(let start, let end, let color, let lineWidth):
            return .arrow(start: EditorCanvasState.Point(start),
                          end: EditorCanvasState.Point(end),
                          color: EditorCanvasState.Color(color),
                          lineWidth: lineWidth)
        case .rect(let rect, let color, let lineWidth):
            return .rect(rect: EditorCanvasState.Rect(rect),
                         color: EditorCanvasState.Color(color),
                         lineWidth: lineWidth)
        case .ellipse(let rect, let color, let lineWidth):
            return .ellipse(rect: EditorCanvasState.Rect(rect),
                            color: EditorCanvasState.Color(color),
                            lineWidth: lineWidth)
        case .text(let text):
            return .text(EditorCanvasState.Text(text: text.text,
                                                origin: EditorCanvasState.Point(text.origin),
                                                color: EditorCanvasState.Color(text.color),
                                                fontSize: text.fontSize))
        case .image(let image, let rect):
            guard let pngData = ScreenshotServiceCoreLogic.pngData(from: image) else { return nil }
            return .image(pngData: pngData, rect: EditorCanvasState.Rect(rect))
        case .erase(let rect):
            return .erase(rect: EditorCanvasState.Rect(rect))
        }
    }
}

private final class EditorInlineTextView: NSTextView {
    var onCommit: (() -> Void)?
    var onCancel: (() -> Void)?
    var onDidChange: (() -> Void)?

    override func keyDown(with event: NSEvent) {
        let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
        switch event.keyCode {
        case 36, 76: // Return / Enter
            if flags.contains(.shift) {
                super.keyDown(with: event)
            } else {
                onCommit?()
            }
        case 53: // Escape
            onCancel?()
        default:
            super.keyDown(with: event)
        }
    }

    override func didChangeText() {
        super.didChangeText()
        onDidChange?()
    }
}

import AppKit

/// Routes command-key equivalents before AppKit's window/menu handling can
/// consume them. The canvas remains the first responder during normal editing;
/// inline text editors intentionally keep their standard text undo manager.
final class EditorWindow: NSWindow {
    override func performKeyEquivalent(with event: NSEvent) -> Bool {
        let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
        let chars = event.charactersIgnoringModifiers?.lowercased()

        if chars == "z", let canvas = firstResponder as? EditorCanvasView {
            if flags == [.command] {
                canvas.undo()
                return true
            }
            if flags == [.command, .shift] {
                canvas.redo()
                return true
            }
        }

        return super.performKeyEquivalent(with: event)
    }
}

/// Window controller for the screenshot editor.
///
/// The editor provides basic annotation tools (pen, arrow, rectangle,
/// ellipse, text), a small color palette with keyboard access, an undo
/// stack, and zoom controls. When the user finishes (save, copy+save,
/// copy+delete, delete), the controller calls `onComplete` with the
/// final image and desired action. The caller (ScreenshotWorkflowController)
/// is responsible for writing the image to disk, clipboard operations,
/// and backup/delete semantics.
final class EditorWindowController: NSWindowController {
    typealias FinalAction = ScreenshotWorkflowController.FinalAction

    /// Called when the user finishes editing.
    /// - Parameters:
    ///   - image: The final composited image, or `nil` for delete-only.
    ///   - action: The requested final action.
    var onComplete: ((NSImage?, FinalAction, EditorCanvasState?) -> Void)?
    var onBackToNote: (() -> Void)?
    /// Confirmation callbacks for Esc/X paths. Cancelling keeps drawings intact.
    /// The setting gates both callbacks; nil proceeds without a prompt.
    var onConfirmDelete: (() -> Bool)?
    var onConfirmClose: (() -> Bool)?

    private let canvasView: EditorCanvasView
    private let scrollView = EditorScrollView()
    private let clipboardService = ClipboardService()
    private let settingsStore: SettingsStore
    private let notePreviewRaw: String?
    private let targetScreen: NSScreen?
    private var notePreviewContainer: NSView?
    // Toolbar Cancel (X) and the red window close button mirror Escape:
    // - For editor sessions that own the temp file: delete on cancel.
    // - For Finder-selected originals: close without deleting.
    private let escapeFinalActionCommand: EditorCanvasView.FinalActionCommand

    private var escapeFinalAction: FinalAction {
        escapeFinalActionCommand == .closeOnly ? .closeOnly : .deleteOnly
    }

    private var toolButtons: [EditorTool: NSButton] = [:]
    private var colorPickerButtons: [NSButton] = []
    private var colorPickerPopover = NSPopover()
    private var colorFocusIndex = 0
    private var selectedColorIndex = 0

    private let colorIndicatorButton = NSButton(frame: .zero)
    private let zoomLabel = NSTextField(labelWithString: "100%")

    private let colors: [NSColor] = [
        NSColor(hex: "#ff3b30"),
        NSColor(hex: "#007aff"),
        NSColor(hex: "#34c759"),
        NSColor(hex: "#000000"),
        NSColor(hex: "#ffcc00"),
        NSColor(hex: "#ffffff")
    ]

    // Match mac_screenshot behavior:
    // - The window opens sized to the image (with caps).
    // - The image may be scaled down to fit (baseScale <= 1).
    // - Zoom controls are relative to that baseScale (start at 100%).
    private var userZoomFactor: CGFloat = 1.0
    private var baseScale: CGFloat = 1.0
    private var defaultUserZoomFactor: CGFloat = 1.0
    // Total padding amount around the image (not per-side).
    private var totalPadding: CGFloat = 0.0

    // Auto-zoom small captures so they fill most of the editor canvas.
    private let autoZoomFillRatio: CGFloat = 0.90
    private let maxAutoUserZoom: CGFloat = 2.0

    // User zoom bounds (multiplier relative to fit).
    private let minUserZoom: CGFloat = 0.2
    private let maxUserZoom: CGFloat = 6.0

    // Absolute bounds enforced by NSScrollView.
    private let minEffectiveZoom: CGFloat = 0.02
    private let maxEffectiveZoom: CGFloat = 8.0

    private var didSendCompletion = false
    private var keyDownMonitor: Any?

    private weak var toolbarBackgroundView: NSView?
    private var toolbarMinimumWidth: CGFloat = 520.0
    private var toolbarMinimumHeight: CGFloat = 72.0

    // MARK: - Init

    convenience init?(imageURL: URL,
                      settingsStore: SettingsStore,
                      notePreview: String? = nil,
                      targetScreen: NSScreen? = nil,
                      escapeKeyDeletesFile: Bool = true) {
        guard let image = NSImage(contentsOf: imageURL) else {
            let alert = NSAlert()
            alert.alertStyle = .warning
            alert.messageText = "Unable to open image"
            alert.informativeText = "The captured image could not be loaded for editing."
            alert.addButton(withTitle: "OK")
            alert.runModal()
            return nil
        }
        self.init(image: image,
                  settingsStore: settingsStore,
                  notePreview: notePreview,
                  targetScreen: targetScreen,
                  escapeKeyDeletesFile: escapeKeyDeletesFile)
    }

    init(image: NSImage,
         settingsStore: SettingsStore,
         notePreview: String? = nil,
         targetScreen: NSScreen? = nil,
         escapeKeyDeletesFile: Bool = true,
         initialState: EditorCanvasState? = nil) {
        let escapeFinal: EditorCanvasView.FinalActionCommand = escapeKeyDeletesFile ? .deleteOnly : .closeOnly
        // A pending composite already contains the current annotations. When
        // editable state is available, restore its clean base image instead and
        // redraw the annotations exactly once.
        let canvasImage: NSImage
        if let initialState, initialState.isSafeToRestore(),
           let restoredBase = NSImage(data: initialState.baseImagePNG) {
            canvasImage = restoredBase
        } else {
            canvasImage = image
        }
        self.canvasView = EditorCanvasView(
            image: canvasImage,
            escapeFinalAction: escapeFinal,
            initialState: initialState?.isSafeToRestore() == true ? initialState : nil
        )
        self.settingsStore = settingsStore
        self.notePreviewRaw = notePreview
        self.targetScreen = targetScreen
        self.escapeFinalActionCommand = escapeFinal

        // Provisional size. We'll resize to match the image (native-like) after building UI.
        let contentRect = NSRect(x: 0, y: 0, width: 720, height: 520)

        let style: NSWindow.StyleMask = [.titled, .closable, .miniaturizable, .resizable, .fullSizeContentView]
        let window = EditorWindow(contentRect: contentRect,
